def _prima_modifica(Registro, tabella, ids):
    voce = Registro.objects.filter(tabella=tabella, oggetto_id__in=[str(i) for i in ids]).exclude(azione="ELIMINA").order_by("quando").first()
    return (voce.utente_id, voce.quando) if voce and voce.utente_id else None


def ricava_compilatore(apps, schema_editor):
    """Per i documenti già esistenti: chi li ha creati o modificati per primo secondo il registro modifiche (anche
    tramite le prove delle funzioni), altrimenti chi li ha inviati in verifica, altrimenti l'autore della revisione."""
    Registro = apps.get_model("rischi", "RegistroModifica")
    Prove = apps.get_model("rischi", "ProveFunzione")
    for nome, tabella in (("ValidazioneSicurezza", "validazione delle funzioni di sicurezza"),
                          ("VerificaElettrica", "verifica elettrica")):
        for doc in apps.get_model("rischi", nome).objects.filter(compilata_da__isnull=True).select_related("revisione"):
            candidati = [_prima_modifica(Registro, tabella, [doc.pk])]
            if nome == "ValidazioneSicurezza":
                prove = list(Prove.objects.filter(validazione_id=doc.pk).values_list("pk", flat=True))
                candidati.append(_prima_modifica(Registro, "prove di validazione della funzione", prove))
            candidati = [c for c in candidati if c]
            if candidati:
                doc.compilata_da_id, doc.compilata_il = min(candidati, key=lambda c: c[1])
            elif doc.inviata_da_id:
                doc.compilata_da_id, doc.compilata_il = doc.inviata_da_id, doc.inviata_il
            else:
                doc.compilata_da_id, doc.compilata_il = doc.revisione.compilata_da_id, doc.revisione.creata_il
            doc.save(update_fields=["compilata_da", "compilata_il"])


